sealed class AttemptWorker(
    IAttemptStore store,
    IBus bus,
    IClock clock)
{
    public async Task HandleAsync(string messageId, string body, CancellationToken ct)
    {
        var attempt = new Attempt(messageId, clock.UtcNow);
        await store.SaveAsync(attempt, ct);
        await bus.PublishAsync(attempt.Id, ct);
    }
}

abstract class TokenParser
{
    public AuthToken Parse(string raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            throw new ArgumentException("Token required");
        return ParseCore(raw);
    }
    protected abstract AuthToken ParseCore(string raw);
}

sealed class LtiTokenParser : TokenParser
{
    protected override AuthToken ParseCore(string raw) =>
        new AuthToken(raw, "lti");
}

