// BEFORE: inheritance couples every notifier to SMTP details
abstract class BaseNotifier
{
    protected abstract Task SendCoreAsync(string to, string body);
    public Task SendAsync(string to, string body) => SendCoreAsync(to, body);
}
class SmtpNotifier : BaseNotifier { /* ... */ }

// AFTER: composition — swap channel without subclassing
interface INotifier { Task SendAsync(string to, string body, CancellationToken ct); }
sealed class SmtpNotifier(IEmailClient client) : INotifier
{
    public Task SendAsync(string to, string body, CancellationToken ct) =>
        client.SendAsync(to, body, ct);
}

// Host wires the implementation; worker depends on INotifier only
builder.Services.AddSingleton<INotifier, SmtpNotifier>();
